def pbHasMegaRing?(idxBattler)
  if pbOwnedByPlayer?(idxBattler)
    @mega_rings.each { |item| return true if $bag.has?(item) }
  else
    trainer_items = pbGetOwnerItems(idxBattler)
    return false if !trainer_items
    @mega_rings.each { |item| return true if trainer_items.include?(item) }
  end
  return false
end

def pbRegisterMegaEvolution(idxBattler)
  side  = @battlers[idxBattler].idxOwnSide
  owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
  @megaEvolution[side][owner] = idxBattler
end

def pbUnregisterMegaEvolution(idxBattler)
  side  = @battlers[idxBattler].idxOwnSide
  owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
  @megaEvolution[side][owner] = -1 if @megaEvolution[side][owner] == idxBattler
end

def pbFaint(showMessage = true)
  if !fainted?
    PBDebug.log("!!!***Can't faint with HP greater than 0")
    return
  end
  return if @fainted   # Has already fainted properly
  @battle.pbDisplayBrief(_INTL("{1} fainted!", pbThis)) if showMessage
  PBDebug.log("[Pokémon fainted] #{pbThis} (#{@index})") if !showMessage
  @battle.scene.pbFaintBattler(self)
  @battle.pbSetDefeated(self) if opposes?
  pbInitEffects(false)
  # Reset status
  self.status      = :NONE
  self.statusCount = 0
  # Lose happiness
  if @pokemon && @battle.internalBattle
    badLoss = @battle.allOtherSideBattlers(@index).any? { |b| b.level >= self.level + 30 }
    @pokemon.changeHappiness((badLoss) ? "faintbad" : "faint")
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  @pokemon.makeUnmega if mega?
  @pokemon.makeUnprimal if primal?
  # Do other things
  @battle.pbClearChoice(@index)   # Reset choice
  pbOwnSide.effects[PBEffects::LastRoundFainted] = @battle.turnCount
  if $game_temp.party_direct_damage_taken &&
     $game_temp.party_direct_damage_taken[@pokemonIndex] &&
     pbOwnedByPlayer?
    $game_temp.party_direct_damage_taken[@pokemonIndex] = 0
  end
  # Check other battlers' abilities that trigger upon a battler fainting
  pbAbilitiesOnFainting
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end

def initialize(scene, p1, p2, player, opponent)
  if p1.length == 0
    raise ArgumentError.new(_INTL("Party 1 has no Pokémon."))
  elsif p2.length == 0
    raise ArgumentError.new(_INTL("Party 2 has no Pokémon."))
  end
  @scene             = scene
  @peer              = Peer.new
  @field             = ActiveField.new    # Whole field (gravity/rooms)
  @sides             = [ActiveSide.new,   # Player's side
                        ActiveSide.new]   # Foe's side
  @positions         = []                 # Battler positions
  @battlers          = []
  @sideSizes         = [1, 1]   # Single battle, 1v1
  @backdrop          = ""
  @backdropBase      = nil
  @time              = 0
  @environment       = :None   # e.g. Tall grass, cave, still water
  @turnCount         = 0
  @decision          = 0
  @caughtPokemon     = []
  player   = [player] if !player.nil? && !player.is_a?(Array)
  opponent = [opponent] if !opponent.nil? && !opponent.is_a?(Array)
  @player            = player     # Array of Player/NPCTrainer objects, or nil
  @opponent          = opponent   # Array of NPCTrainer objects, or nil
  @items             = nil
  @ally_items        = nil        # Array of items held by ally. This is just used for Mega Evolution for now.
  @party1            = p1
  @party2            = p2
  @party1order       = Array.new(@party1.length) { |i| i }
  @party2order       = Array.new(@party2.length) { |i| i }
  @party1starts      = [0]
  @party2starts      = [0]
  @internalBattle    = true
  @debug             = false
  @canRun            = true
  @canLose           = false
  @canSwitch         = true
  @switchStyle       = true
  @showAnims         = true
  @controlPlayer     = false
  @expGain           = true
  @moneyGain         = true
  @disablePokeBalls  = false
  @sendToBoxes       = 1
  @rules             = {}
  @priority          = []
  @priorityTrickRoom = false
  @choices           = []
  @megaEvolution     = [
    [-1] * (@player ? @player.length : 1),
    [-1] * (@opponent ? @opponent.length : 1)
  ]
  @initialItems      = [
    Array.new(@party1.length) { |i| (@party1[i]) ? @party1[i].item_id : nil },
    Array.new(@party2.length) { |i| (@party2[i]) ? @party2[i].item_id : nil }
  ]
  @recycleItems      = [Array.new(@party1.length, nil),   Array.new(@party2.length, nil)]
  @belch             = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @battleBond        = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @corrosiveGas      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @usedInBattle      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @successStates     = []
  @lastMoveUsed      = nil
  @lastMoveUser      = -1
  @switching         = false
  @futureSight       = false
  @command_phase     = false
  @endOfRound        = false
  @moldBreaker       = false
  @runCommand        = 0
  @nextPickupUse     = 0
  @struggle          = Move::Struggle.new(self, nil)
  @mega_rings        = []
  GameData::Item.each { |item| @mega_rings.push(item.id) if item.has_flag?("MegaRing") }
  @battleAI          = AI.new(self)
end

def form=(value)
  @form = value
  @pokemon.form = value if @pokemon
end

def hp=(value)
  @hp = value.to_i
  @pokemon.hp = value.to_i if @pokemon
end

def pbInitPokemon(pkmn, idxParty)
  raise _INTL("An egg can't be an active Pokémon.") if pkmn.egg?
  @name         = pkmn.name
  @species      = pkmn.species
  @form         = pkmn.form
  @level        = pkmn.level
  @hp           = pkmn.hp
  @totalhp      = pkmn.totalhp
  @types        = pkmn.types
  @ability_id   = pkmn.ability_id
  @item_id      = pkmn.item_id
  @attack       = pkmn.attack
  @defense      = pkmn.defense
  @spatk        = pkmn.spatk
  @spdef        = pkmn.spdef
  @speed        = pkmn.speed
  @status       = pkmn.status
  @statusCount  = pkmn.statusCount
  @pokemon      = pkmn
  @pokemonIndex = idxParty
  @participants = []   # Participants earn Exp. if this battler is defeated
  @moves        = []
  pkmn.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, m)
  end
end

def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end
